async function upload(key){let thumbnailPending=false;status='Enviando foto…';document.querySelector('.save-state')?.replaceChildren(document.createTextNode(status));if(!caps.photosEnabled)throw Error('Armazenamento indisponível; nenhum envio confirmado.');if(key.startsWith('equipment:')&&!itemVersion)await saveDraft();else if(screen==='group'||screen==='facade')await save();const [kind,id]=key.split(':'),list=previews.get(key)||[];while(list.length){const p=list[0];const received=await api('/api/collector/photo-upload',null,{method:'POST',headers:{'Content-Type':p.blob.type,'X-CSRF-Token':me.csrf,'X-Photo-Id':p.id,'X-Inspection-Id':collection.inspection.id,'X-Target-Kind':kind,'X-Target-Id':id},body:p.blob});if(received.status!=='ready')throw Error('Recebimento da foto ainda não confirmado.');try{if(p.thumbnail)await api('/api/collector/photo-thumb',null,{method:'POST',headers:{'Content-Type':'image/jpeg','X-CSRF-Token':me.csrf,'X-Photo-Id':p.id,'X-Inspection-Id':collection.inspection.id,'X-Source-SHA256':received.sha256||await photoHash(p.blob)},body:p.thumbnail});}catch{thumbnailPending=true;}URL.revokeObjectURL(p.url);list.shift();}const fresh=await api('/api/collector/inspection?id='+collection.inspection.id);collection.photos=fresh.photos;status=thumbnailPending?'Foto recebida. Miniatura pendente; a foto completa está disponível.':'Fotografia recebida pelo servidor';}
