app.addEventListener('input',e=>{if(renderedContext!==contextKey()||!app.contains(e.target)||sectionLocked())return;if(!e.target.dataset.field)return;const key=e.target.dataset.field;if(key==='_query'){query=e.target.value;return;}if(key.startsWith('_pairing.')){pairing??={};pairing[key.slice(9)]=e.target.value;return;}write(key,e.target.value);if(screen==='equipment'){itemSaved=false;refreshFichaState();}else{dirty=true;status='Alterações nesta aba';clearTimeout(timer);timer=setTimeout(saveSoon,600);}});
app.addEventListener('change',e=>{if(renderedContext!==contextKey()||!app.contains(e.target)||sectionLocked())return;if(e.target.dataset.field==='_query'){query=e.target.value;return;}if(e.target.dataset.field?.startsWith('_pairing.')){pairing??={};pairing[e.target.dataset.field.slice(9)]=e.target.type==='checkbox'?e.target.checked:e.target.value;return;}if(e.target.dataset.field){const key=e.target.dataset.field;write(key,e.target.value);if(screen==='equipment')itemSaved=false;else{dirty=true;clearTimeout(timer);timer=setTimeout(saveSoon,600);}if(e.target.tagName==='SELECT')render();}if(e.target.id==='category-filter'){filter=e.target.value;cursor=null;loadItems().then(render).catch(showError);}if(e.target.dataset.photo){if(photoBusy)return;photoBusy=true;status='Preparando e enviando foto…';document.querySelector('.save-state')?.replaceChildren(document.createTextNode(status));preparePhotos(e.target).catch(showError).finally(()=>{e.target.value='';photoBusy=false;render();});}});
let errorSession=false;
async function recoverSession(){
 const authenticated=await api('/api/auth/me');
 if(authenticated.username!==me.username)throw Object.assign(Error('Entre com o mesmo usuário desta coleta ('+me.username+'). As respostas permanecem nesta aba.'),{session:true});
 if(!['root','admin','operador'].includes(authenticated.role))throw Error('Perfil sem permissão de coleta.');
 me=authenticated;
 if(itemVersion&&item&&screen==='equipment'){
  const r=await api('/api/collector/equipment-lock',{inspectionId:collection.inspection.id,id:item.id});
  if(r.equipment.version!==itemVersion){await api('/api/collector/equipment-unlock',{id:item.id,token:r.token});lock=null;throw Error('Outra sessão alterou esta ficha. Suas respostas continuam nesta aba; confira o conflito antes de salvar.');}
  lock=r.token;
 }
 errorSession=false;error='';status='Sessão recuperada. Confira as respostas e toque em Salvar.';
}
function showError(e){status=e.session?'Alterações não enviadas':'Operação não confirmada';error=e.message;errorSession=!!e.session;fields=e.fields||{};if(Array.isArray(e.pending)&&screen==='inventory')inlinePending=e.pending;const key=Object.keys(fields)[0]?.split('.')[0];if(screen==='group'&&key){const index=(v2Sections[topic]||[]).filter(f=>shown(f,answers,{})).findIndex(f=>f.key===key);if(index>=0)step=index;}if(screen==='equipment'&&key){step=['category','registration','manualReason','mode'].includes(key)?0:['environment','assetStatus','asset','brand','model','serial'].includes(key)?1:2;}render();ux.focusError();}
async function preparePhotos(input){const key=input.dataset.photo,list=previews.get(key)||[],sent=collection.photos.filter(p=>p.target_kind+':'+p.target_id===key&&p.status==='ready'&&p.current).length;if(sent+list.length+input.files.length>5)throw Error('Máximo de cinco fotos por registro.');for(const file of input.files){const prepared=await preparePhoto(file),total=[...previews.values()].flat().reduce((sum,p)=>sum+p.blob.size+(p.thumbnail?.size||0),0)+prepared.blob.size+prepared.thumbnail.size;if(total>40*1024*1024)throw Error('Envie as prévias antes de selecionar mais fotografias.');list.push({id:crypto.randomUUID(),blob:prepared.blob,thumbnail:prepared.thumbnail,url:URL.createObjectURL(prepared.blob)});previews.set(key,list);}render();await upload(key);render();}
async function scanAgentQr(){
 item.data.registration='Agente';
 // [REV-05] a leitura e a prévia não exigem nada além do tipo: nenhuma gravação antes de abrir o leitor.
 const text=await scanPairingQr();if(!text)return;
 const qr=parsePairingQr(text);
 const preview=await api('/api/agent/v1/pairings/preview',{enrollment_id:qr.enrollment_id,pairing_code:qr.pairing_code,unit_id:collection.unit.id});
 const suggested=(preview.equipment_suggestions||[]).find(x=>x.equipment_id===item.id);
 pairing={qr,preview,requestId:crypto.randomUUID(),positionLabel:item.data.position_label||item.position_label||'',positionDescription:item.position_description||'',confirmed:false,locationChange:null,reason:'',alreadyLinked:!!suggested?.already_linked};
 if(pairing.alreadyLinked){pairing=null;throw Error('Esta ficha já possui um agente ativo. Use reconciliação administrativa (root) antes de vincular outro.');}
 status='QR lido neste aparelho; vínculo ainda não confirmado';
}
// [R2-A] Comando congelado: request_id + corpo são fixados ANTES do envio e repetidos IDÊNTICOS enquanto o resultado for desconhecido
// (resposta perdida, rede). Recusa confirmada pelo servidor resolve o comando (novo request_id para a próxima tentativa); resultado
// desconhecido é reconciliado consultando o RECIBO pelo request_id antes de reenviar. Nunca se declara sucesso sem resposta do servidor.
const UNKNOWN_MSG='Sem resposta do servidor: o resultado é desconhecido. Toque de novo em "Verificar / repetir confirmação" — o mesmo comando será conferido e repetido, sem duplicar nada.';
function resolveCommand(kind){if(!pairing)return;pairing[kind]=null;if(kind==='command')pairing.requestId=crypto.randomUUID();}
async function lookupReceipt(statusPath,requestId){try{return await api(statusPath+'?request_id='+encodeURIComponent(requestId));}catch(e){if(e.unknown)throw Error(UNKNOWN_MSG);throw e;}}
async function sendCommand(kind,path,statusPath){
 const cmd=pairing[kind];if(!cmd)throw Error('Nenhum comando pendente.');
 if(cmd.unknown){ // resultado anterior desconhecido: primeiro o recibo, depois (se não houver) o MESMO corpo de novo
  const receipt=await lookupReceipt(statusPath,cmd.body.request_id);
  if(receipt.found){cmd.unknown=false;return receipt.body;}
 }
 try{const r=await api(path,cmd.body);cmd.unknown=false;return r;}
 catch(e){
  if(e.unknown){cmd.unknown=true;status='Resultado desconhecido: confirme de novo para verificar';throw Error(UNKNOWN_MSG);}
  if(e.code==='REQUEST_ID_CONFLICT'){cmd.unknown=true;const receipt=await lookupReceipt(statusPath,cmd.body.request_id);if(receipt.found){cmd.unknown=false;return receipt.body;}throw Error(UNKNOWN_MSG);}
  if(e.code==='LOCK_REQUIRED'){ // trava expirada: o servidor recusa ANTES de gravar (sem recibo), então o mesmo request_id pode seguir com a trava renovada
   const l=await api('/api/collector/equipment-lock',{inspectionId:collection.inspection.id,id:item.id,token:lock});lock=l.token;cmd.body={...cmd.body,lock_token:lock};
   try{const r=await api(path,cmd.body);cmd.unknown=false;return r;}catch(e2){if(e2.unknown){cmd.unknown=true;throw Error(UNKNOWN_MSG);}throw e2;}
  }
  throw e; // recusa confirmada: quem chamou decide (comando resolvido)
 }
}
function applyClaim(r,label){item.agent_linked=true;item.agent_link={link_id:r.link_id,linked_at:r.linked_at};item.position_label=r.position?.label||label;item.data.position_label=item.position_label;item.location_state=r.location_state;item.data.registration='Agente';itemVersion=r.equipment_version;pairing=null;status=r.duplicate?'Computador vinculado · confirmado pelo servidor (recibo do comando anterior)':'Computador vinculado · confirmado pelo servidor';}
// Conflito de versão: a ficha do servidor substitui a desta aba (explícito na mensagem); nada local sobrescreve a edição alheia.
async function reloadFromServer(){const l=await api('/api/collector/equipment-lock',{inspectionId:collection.inspection.id,id:item.id,token:lock});const fresh=l.equipment;item={...item,...fresh,data:{mode:'Individual',quantity:1,...fresh.data},agent_linked:!!l.agent_linked||!!fresh.agent_linked,agent_link:l.agent_link||item.agent_link};itemVersion=fresh.version;lock=l.token;itemSaved=true;}
// REV-04: posição do computador vinculado confirmada no ambiente ATUAL da ficha (rota de localização, mesma política de trava/visita/assunto).
async function confirmPosition(){
 pairing??={};
 if(!pairing.positionCommand){
  const label=String(item.data.position_label||'').trim();if(!label)throw Error('Informe a posição no ambiente (ex.: Bancada 2 / PC 7).');if(!item.data.environment)throw Error('Selecione o ambiente da ficha (etapa 2).');if(!itemSaved)await saveItem();
  pairing.positionCommand={unknown:false,label,body:{request_id:crypto.randomUUID(),equipment_id:item.id,expected_version:itemVersion,environment_id:item.data.environment,position:{label,description:String(pairing.positionDescription||'').trim()||undefined},reason:'Posição confirmada na visita pelo coletor',inspection_id:collection.inspection.id,lock_token:lock||''}};
 }
 const label=pairing.positionCommand.label;
 try{const r=await sendCommand('positionCommand','/api/inventory/equipment-location','/api/inventory/equipment-location-status');item.position_label=label;item.location_state=r.location?.location_state||'confirmada_em_visita';itemVersion=r.equipment_version;pairing=null;status='Posição confirmada · registrada pelo servidor';}
 catch(e){
  if(e.message===UNKNOWN_MSG)throw e;
  resolveCommand('positionCommand');
  if(e.code==='EQUIPMENT_VERSION_CONFLICT'){await reloadFromServer();throw Error('A ficha foi alterada em outra sessão. Dados do servidor recarregados; confira a posição e confirme novamente.');}
  if(e.code==='EQUIPMENT_LOCKED')throw Error('Outro usuário está editando esta ficha. Aguarde a liberação.');
  if(e.code==='SECTION_COMPLETED')throw Error('O assunto Computadores desta visita está concluído. Volte às categorias e reabra Computadores antes de mover a ficha.');
  throw e;}}
async function confirmAgentLink(){
 if(!pairing?.preview)throw Error('Leia o QR do agente primeiro.');
 if(!pairing.command){ // primeiro envio: validações locais, rascunho mínimo (REV-05) e congelamento do comando
  if(!item.data.environment)throw Error('Selecione o ambiente da ficha antes de vincular.');
  
  const label=String(item.data.position_label||'').trim();if(!label)throw Error('Informe a posição no ambiente (ex.: Bancada 2 / PC 7).');
  
  if(!itemVersion||item.data.draft===true)await saveDraft();else if(!itemSaved)await saveItem();
  const body={request_id:pairing.requestId,enrollment_id:pairing.qr.enrollment_id,pairing_code:pairing.qr.pairing_code,unit_id:collection.unit.id,environment_id:item.data.environment,inspection_id:collection.inspection.id,equipment:{mode:'existing',equipment_id:item.id,expected_version:itemVersion},position:{label,description:String(pairing.positionDescription||'').trim()||undefined},lock_token:lock||''};
  
  pairing.command={unknown:false,label,body};
 }
 const label=pairing.command.label;
 try{const r=await sendCommand('command','/api/agent/v1/pairings/claim','/api/agent/v1/pairings/claim-status');applyClaim(r,label);await load();}
 catch(e){
  if(e.message===UNKNOWN_MSG)throw e; // comando continua pendente; próxima confirmação verifica o recibo e repete o MESMO corpo
  resolveCommand('command');
  if(e.code==='LOCATION_MISMATCH'){const cur=e.details?.current_location;pairing.locationChange={current:[cur?.environment_name,cur?.position_label].filter(Boolean).join(' · ')||'localização anterior'};throw Error('A ficha estava registrada em outro ambiente/posição. Informe o motivo da mudança e confirme novamente.');}
  if(e.code==='EQUIPMENT_VERSION_CONFLICT'){await reloadFromServer();throw Error('A ficha foi alterada em outra sessão. Os dados do servidor foram recarregados e substituíram as respostas não salvas desta aba; confira e confirme novamente.');}
  if(e.code==='EQUIPMENT_LOCKED')throw Error('Outro usuário está editando esta ficha. Aguarde a liberação e tente de novo.');
  if(e.code==='SECTION_COMPLETED')throw Error('O assunto Computadores desta visita está concluído. Volte às categorias e reabra Computadores (confirmação explícita) antes de vincular.');
  if(['PAIRING_EXPIRED','PAIRING_CONSUMED','PAIRING_LOCKED','ENROLLMENT_NOT_FOUND','PAIRING_CODE_INVALID'].includes(e.code)){pairing=null;throw Error((e.message||'QR inválido')+' Gere um novo QR na máquina e leia novamente.');}
  if(e.code==='DEVICE_REVOKED'){pairing=null;throw Error('Este agente foi revogado. Reinstale/autorize novamente antes de vincular.');}
  throw e;
 }
}
async function searchInventory(){if(busy||photoBusy||screen!=='inventory')return;busy=true;const input=app.querySelector('[data-field="_query"]');query=input.value;appliedQuery=query.trim();cursor=null;input.blur();try{await loadItems();repaint();}catch(e){showError(e);}finally{busy=false;}}
app.addEventListener('search',e=>{if(e.target.dataset.field==='_query'&&!e.target.value)searchInventory();});
app.addEventListener('submit',async e=>{if(e.target.id==='equipment-search'){e.preventDefault();await searchInventory();return;}if(e.target.id!=='environment-form')return;e.preventDefault();if(busy)return;busy=true;try{const form=new FormData(e.target),payload={inspectionId:collection.inspection.id,name:form.get('name'),type:''};let r;try{r=await api('/api/collector/environment-save',payload);}catch(err){if(!Array.isArray(err.similar)||!err.similar.length)throw err;if(!await confirmCollection('Já existe ambiente com nome parecido nesta unidade:\n• '+err.similar.map(x=>x.name).join('\n• ')+'\n\nCadastrar mesmo assim como um ambiente diferente?'))throw Error('Cadastro cancelado. Selecione o ambiente existente ou ajuste o nome.');r=await api('/api/collector/environment-save',{...payload,confirmSimilar:true});}await load();status=r.existing?'Ambiente existente reutilizado':'Ambiente cadastrado no servidor';render();}catch(e){showError(e);}finally{busy=false;}});
app.addEventListener('click',async e=>{const t=e.target.closest('[data-action]');if(!t||t.dataset.action==='close-keyboard'||busy||photoBusy)return;busy=true;t.disabled=true;const a=t.dataset.action;let restoreScroll;if(screen==='inventory'&&['edit','new'].includes(a)){inventoryScroll=scrollY;rememberInventory();}error='';errorSession=false;fields={};try{
 if(a==='cards'){await leave();fromReview=false;inlinePending=null;screen='cards';}
 else if(a==='facade')await openFacade();
 else if(a==='companion')await open('A');
 else if(a==='open')await open(t.dataset.topic);
 else if(a==='save'){await save();}
 else if(a==='recover-session'){await recoverSession();}
 else if(a==='complete'){await save();await api('/api/collector/section-save',{inspectionId:collection.inspection.id,section:topic,version:collection.sections[topic].version,answers,complete:true});drafts.forget(collection.inspection.id,topic);await load();screen='cards';}
 else if(a==='add-row'){const list=read(t.dataset.path)||[];list.push({id:crypto.randomUUID()});write(t.dataset.path,list);dirty=true;saveSoon();}
 else if(a==='remove-row'){if(await confirmCollection('Remover este registro? A alteração ficará no histórico.')){read(t.dataset.path).splice(Number(t.dataset.index),1);dirty=true;saveSoon();}}
 else if(a==='choose-environment')await selectEnvironment();
 else if(a==='refresh-environments')await loadEnvironments();
 else if(a==='rename-environment'){
  await loadEnvironments();const room=collection.environments.find(e=>e.id===t.dataset.id);if(!room)throw Error('Ambiente não encontrado. Atualize a lista.');
  const renamed=await editEnvironmentName({environment:room,save:payload=>api('/api/collector/environment-rename',{...payload,inspectionId:collection.inspection.id})});
  if(renamed){collection.environments=collection.environments.map(e=>e.id===renamed.id?renamed:e);if(item?.data.environment===renamed.id)item.data.environmentName=renamed.name;status='Nome do ambiente atualizado no servidor';}
 }

 else if(a==='search'){appliedQuery=query.trim();cursor=null;await loadItems();}
 else if(a==='clear-search'){query='';appliedQuery='';cursor=null;await loadItems();}
 else if(a==='next-page'){await loadItems({append:true});}
 else if(a==='refresh-list'){cursor=null;await loadItems();}
 else if(a==='new')await newItem();
 else if(a==='edit'){await openEquipment(t.dataset.id,topic);}
 else if(a==='resume'){await resumeEquipment();}
 else if(a==='manual'){item.data.registration='Manual';pairing=null;itemSaved=false;}
 else if(a==='qr-scan'){await scanAgentQr();}
 else if(a==='qr-cancel'){if(pairing?.command?.unknown&&!await confirmCollection('O último envio ficou sem resposta e ainda não foi verificado. Cancelar mesmo assim? O vínculo pode ter sido gravado; confira a ficha depois.'))return;pairing=null;}
 else if(a==='qr-confirm'){await confirmAgentLink();}
 else if(a==='position-confirm'){await confirmPosition();}
 else if(a==='item-previous'){await leave();if(fromReview){fromReview=false;reviewData=await api('/api/collector/review?id='+collection.inspection.id);screen='review';}else{screen='inventory';await loadItems({restore:true});restoreScroll=inventoryScroll;}}
 else if(a==='save-item'){if(!await saveItem()){render();return;}if(previews.get('equipment:'+item.id)?.length)await upload('equipment:'+item.id);await leave();item=null;if(fromReview){fromReview=false;reviewData=await api('/api/collector/review?id='+collection.inspection.id);screen='review';status='Ficha salva · revisão atualizada';}else{screen='inventory';inlinePending=null;await loadItems({restore:true});restoreScroll=inventoryScroll;}}
 else if(a==='complete-inventory'){await save();await api('/api/collector/inventory-section',{inspectionId:collection.inspection.id,section:topic,version:collection.sections[topic].version});drafts.forget(collection.inspection.id,topic);inlinePending=null;await load();screen='cards';}
 else if(a==='upload')await upload(t.dataset.key);
 else if(a==='view-photo'){const photo=collection.photos.find(p=>p.id===t.dataset.photoId);if(photo)viewCollectorPhoto(photo,t);}
 else if(a==='remove-photo'){if(await confirmCollection('Remover esta fotografia?')){await api('/api/collector/photo-remove',{id:t.dataset.photoId});const fresh=await api('/api/collector/inspection?id='+collection.inspection.id);collection.photos=fresh.photos;}}
 else if(a==='remove-preview'){const [p]=previews.get(t.dataset.key).splice(Number(t.dataset.index),1);URL.revokeObjectURL(p.url);}
 else if(a==='review'){await leave();await load();reviewData=await api('/api/collector/review?id='+collection.inspection.id);screen='review';}
 else if(a==='fix'){const key=t.dataset.error;if(key.startsWith('photo:')){await open('G');}else if(['facade','facadeChanged'].includes(key)){await openFacade();}else if(topics.some(t=>t[0]===key))await open(key);}
 else if(a==='reopen'){const g=topic;if(screen==='equipment')await leave();await open(g);}
 else if(a==='fix-pending'){const {section,kind,id,target}=t.dataset;if(target==='open-facade')await openFacade();else if(kind==='equipment'&&id){const cameFromReview=screen==='review';if(await openEquipment(id,section))fromReview=cameFromReview;}else if(topics.some(x=>x[0]===section))await open(section);}
 else if(a==='finish'){if(!await confirmCollection('Confirmar a conclusão desta visita com os dados recebidos pelo servidor?'))return;const r=await api('/api/collector/finish',{inspectionId:collection.inspection.id,confirm:true,revision:reviewData.revision});if(r.completed){await load();status='Visita concluída e recebida';screen='cards';}}
 else if(a==='units'){if([...previews.values()].some(l=>l.length))throw Error('Envie ou remova as prévias antes de trocar de unidade.');if(item&&!itemSaved&&!await confirmCollection('Descartar a ficha incompleta e trocar de unidade?'))return;await leave();location.assign('/');return;}
 repaint({scroll:restoreScroll??'auto'});
 }catch(e){showError(e);}finally{busy=false;if(t.isConnected){t.disabled=false;if(a==='choose-environment')t.focus({preventScroll:true});}}});
addEventListener('beforeunload',e=>{if(photoBusy||dirty||drafts.hasPending()||item&&!itemSaved||[...previews.values()].some(l=>l.length)){e.preventDefault();e.returnValue='';}});
async function boot(){try{me=await api('/api/auth/me');if(!['root','admin','operador'].includes(me.role))throw Error('Perfil sem permissão de coleta.');caps=await api('/api/collector/capabilities');const u=new URL(location.href),id=u.searchParams.get('vistoria');if(!id){location.replace('/');return;}collection={inspection:{id}};topic=u.searchParams.get('assunto')||'A';if(!topics.some(t=>t[0]===topic))topic='A';await load();screen=['facade','cards','group','inventory','environment','review'].includes(u.searchParams.get('tela'))?u.searchParams.get('tela'):'facade';step=0;if(screen==='group'&&['F','G','O'].includes(topic))screen='inventory';if(topic==='B'&&['group','inventory'].includes(screen))screen='environment';if(collection.inspection.state!=='open')screen='cards';if(screen==='facade'){topic='A';answers=structuredClone(collection.sections.A.data);}if(screen==='inventory')await loadItems();if(topic==='H')await loadSummaryItems();if(screen==='review')reviewData=await api('/api/collector/review?id='+id);repaint();}catch(e){app.innerHTML=`<main class="content"><h1>Não foi possível abrir a coleta</h1><p role="alert">${esc(e.message)}</p><a href="/">Voltar à lista</a></main>`;}}
boot();
